<script setup lang="ts">
import {ref} from 'vue'
import {useZipEditStore} from '@/stores/zipEdit'
import type {ComparisonSide} from '@/types/sourceComparison'
import {open} from '@tauri-apps/api/dialog'
import {archiveInspectionMessageForDisplay} from '@/utils/taskFailure'
import Modal from '@/components/ui/Modal.vue'
import {useSourceComparisonStore} from '@/stores/sourceComparison'
const emit=defineEmits<{close:[];queue:[];prepared:[source:string]}>(),comparison=useSourceComparisonStore()
const mode=ref('retrieve'),base=ref<'left'|'right'|'selected'>('left'),zip=useZipEditStore()
async function compose(){
 if(comparison.busy||!comparison.ready)return
 comparison.busy=true;comparison.error=''
 try{
  const parts=[] as {source:NonNullable<typeof comparison.sides.left.source>['source'];paths?:string[];encoding?:typeof comparison.sides.left.encoding}[]
  if(base.value!=='selected')parts.push({source:comparison.sides[base.value].source!.source,encoding:comparison.sides[base.value].encoding})
  for(const side of ['left','right'] as ComparisonSide[])if(side!==base.value&&comparison.selected[side].size)parts.push({source:comparison.sides[side].source!.source,paths:[...comparison.selected[side]],encoding:comparison.sides[side].encoding})
  const passwords=Object.fromEntries((['left','right'] as ComparisonSide[]).map(side=>[comparison.sides[side].source!.source.path,{password:comparison.sides[side].password,encoding:comparison.sides[side].encoding}]))
  const source=await zip.beginComparison(parts,passwords);emit('prepared',source)
 }catch(error){comparison.error=String(error)}finally{comparison.busy=false}
}
async function choose(){const queued=import.meta.env.VITE_DESKTOP_E2E==='1'?window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection():undefined;const path=queued===undefined?await open({directory:true,title:'选择差异取回位置'}):queued;if(typeof path==='string')comparison.options.outputDirectory=path}
</script>
<template>
 <Modal :visible="true" title="处理所选资料" icon="pi pi-download" size="xl" :show-footer="true" :show-close-button="!comparison.busy" :close-on-backdrop="!comparison.busy" :close-on-escape="!comparison.busy" @update:visible="emit('close')">
  <div class="mode-tabs" role="group" aria-label="处理方式"><button class="button" :aria-pressed="mode==='retrieve'" :disabled="comparison.busy" data-testid="comparison-mode-retrieve" @click="mode='retrieve'">取回文件</button><button class="button" :aria-pressed="mode==='package'" :disabled="comparison.busy" data-testid="comparison-mode-package" @click="mode='package'"><i class="pi pi-box"/>生成新 ZIP</button></div>
  <div v-if="mode==='package'" class="package-card" data-testid="comparison-package-options"><h3>把需要的内容组成下一份交付</h3><p class="note">选择基础后，带入另一侧勾选的文件和空目录；仅所选则合并两侧勾选内容。同名项不会自动覆盖，在下一步逐项确认。</p><label class="package-label">基础内容<select v-model="base" :disabled="comparison.busy" data-testid="comparison-package-base"><option value="left">完整左侧 + 右侧所选</option><option value="right">完整右侧 + 左侧所选</option><option value="selected">仅两侧所选</option></select></label><div class="package-flow"><span>① 选择基础与补充</span><i class="pi pi-angle-right"/><span>② 复核冲突与最终路径</span><i class="pi pi-angle-right"/><span>③ 另存新 ZIP</span></div><p class="note">沿用 ZIP 编辑清单，可撤销、移除、改名和移动。原目录与原包保留；草稿保留来源引用，密码不落入草稿。基础与补充合计最多 10000 项。</p></div>
  <div class="retrieval-grid" :class="{single:mode==='package'}" data-testid="comparison-retrieval-dialog">
   <section class="card"><h3>本次选择 <span>{{ comparison.selectedCount }} 项</span></h3><p class="note">{{ mode==='package' ? '基础内容按上方选择带入，下面列出当前勾选项；下一步查看全部组包内容，原件保留。' : '只处理勾选的文件与空目录，原件保留。来源变化时保留未加入的选择。' }}</p><div class="selection-list custom-scrollbar"><article v-for="side in (['left','right'] as const)" v-show="comparison.selected[side].size" :key="side"><strong>{{ side==='left'?'左侧':'右侧' }} · {{ comparison.sides[side].source?.name }}</strong><p class="note">{{ comparison.selected[side].size }} 项 · {{ comparison.sides[side].source?.source.kind==='zip'?'ZIP 所选提取':'文件夹所选复制' }}</p><p v-if="comparison.issues[side]" class="error" :data-comparison-issue="side">{{ archiveInspectionMessageForDisplay(comparison.issues[side]||'') }} <a href="#/compare" class="link" @click="emit('close')">返回处理来源</a></p><details><summary>查看并调整所选路径</summary><div v-for="path in comparison.selected[side]" :key="path" class="selected-path"><span>{{ path }}</span><button class="link" :disabled="comparison.busy" :aria-label="'移除 '+side+' '+path" @click="comparison.toggle(side,path)">移除</button></div></details></article><p v-if="!comparison.selectedCount" class="note">本批已加入原解压中心，可核对后开始取回。</p></div></section>
   <section v-if="mode==='retrieve'" class="card"><h3>保存方式</h3><fieldset :disabled="comparison.busy" class="fields"><label>取回位置<div class="path-input"><input v-model="comparison.options.outputDirectory" data-testid="comparison-retrieval-output" placeholder="选择或输入保存位置"><button class="button" data-testid="comparison-retrieval-choose-output" @click="choose">选择</button></div></label><label>左右来源<select v-model="comparison.options.separateSides" data-testid="comparison-retrieval-separate"><option :value="true">左右分别放入子目录（推荐）</option><option :value="false">合并到同一个目录</option></select></label><label>文件夹结构<select v-model="comparison.options.keepStructure" data-testid="comparison-retrieval-structure"><option :value="true">保留相对路径</option><option :value="false">放在同一层</option></select></label><label>同名文件<select v-model="comparison.options.conflictPolicy" data-testid="comparison-retrieval-conflict"><option value="rename">自动改名，保留两份</option><option value="skip">跳过已存在项</option></select></label></fieldset><p class="note">来源和所选范围会随任务保留。进入原解压中心查看进度、暂停、停止和实际结果；不覆盖或删除来源。</p></section>
  </div>
  <p v-if="comparison.error" class="error mt-3" role="alert">{{ archiveInspectionMessageForDisplay(comparison.error) }}</p><p v-if="comparison.notice" class="note mt-3" role="status" data-testid="comparison-retrieval-notice">{{ comparison.notice }}</p>
  <template #footer><button class="button" :disabled="comparison.busy" @click="emit('close')">返回</button><button v-if="comparison.admitted" class="button" :disabled="comparison.busy" data-testid="comparison-retrieval-go-queue" @click="emit('queue')">前往解压中心</button><button v-if="mode==='package'" class="button primary" :disabled="comparison.busy||!comparison.selectedCount" data-testid="comparison-package-prepare" @click="compose">{{ comparison.busy?'正在准备清单…':'带入编辑清单，复核后另存' }}</button><button v-else class="button primary" :disabled="comparison.busy||!comparison.selectedCount" data-testid="comparison-retrieval-confirm" @click="comparison.queue">{{ comparison.busy?'正在准备…':'将可用部分加入队列' }}</button></template>
 </Modal>
</template>
<style scoped>
.mode-tabs{display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap}.mode-tabs [aria-pressed="true"]{color:var(--dynamic-accent);border-color:var(--dynamic-accent);background:color-mix(in srgb,var(--dynamic-accent) 8%,transparent)}.package-card{border:1px solid var(--border-subtle);background:var(--bg-card);border-radius:16px;padding:18px;margin-bottom:16px;min-width:0}.package-label{display:block;font-size:12px;margin-top:16px}.package-label select{display:block;width:100%;min-width:0;padding:10px;border:1px solid var(--border-subtle);border-radius:10px;background:var(--bg-input);margin-top:8px;color:var(--text-content)}.package-flow{display:flex;gap:10px;flex-wrap:wrap;align-items:center;font-size:11px;color:var(--dynamic-accent);margin-top:16px}.retrieval-grid.single{grid-template-columns:minmax(0,1fr)}.retrieval-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{min-width:0;border:1px solid var(--border-subtle);border-radius:16px;padding:18px;background:var(--bg-card)}h3{font-size:14px;font-weight:900}h3 span{color:var(--dynamic-accent);margin-left:8px}.note,.error{font-size:11px;line-height:1.9;overflow-wrap:anywhere;color:var(--text-muted);margin-top:10px}.error{color:#d97706}.selection-list{max-height:330px;overflow:auto;margin-top:16px}.selection-list article{border:1px solid var(--border-subtle);border-radius:12px;padding:12px;margin-bottom:10px;font-size:12px;overflow-wrap:anywhere}summary{font-size:11px;cursor:pointer;margin-top:10px;color:var(--dynamic-accent)}.selected-path{display:flex;gap:10px;align-items:center;font-size:11px;line-height:1.8;padding-top:8px}.selected-path span{flex:1;min-width:0;overflow-wrap:anywhere}.link{color:var(--dynamic-accent);font-size:11px;flex-shrink:0}.fields{display:flex;flex-direction:column;gap:18px;margin-top:18px}.fields label{font-size:12px;font-weight:700;min-width:0}.fields input,.fields select{width:100%;min-width:0;border:1px solid var(--border-subtle);border-radius:10px;padding:10px 12px;background:var(--bg-input);font-size:12px;margin-top:8px;color:var(--text-content)}.path-input{display:flex;gap:8px;min-width:0;margin-top:8px}.path-input input{flex:1;margin:0}.path-input button{flex-shrink:0}.button{padding:10px 13px;font-size:12px;border-radius:10px;border:1px solid var(--border-subtle);background:var(--bg-input);color:var(--text-content)}.button.primary{background:var(--dynamic-accent);color:white}.button:disabled,.link:disabled{opacity:.45}@media(max-width:800px){.retrieval-grid{grid-template-columns:minmax(0,1fr)}.card{padding:14px}.selection-list{max-height:200px}}
</style>
